<script setup lang="ts">
import { computed, ref } from 'vue';
import UiParentCard from '@/components/shared/UiParentCard.vue';
import UiModal from '@/components/shared/UiModal.vue';
import type { AdmissionStage } from '../convocatorias.mock';

const props = defineProps<{ convocatoriaId: string; stages: AdmissionStage[] }>();
const emit = defineEmits<{ 'update:stages': [stages: AdmissionStage[]] }>();
const editing = ref<AdmissionStage | null>(null); const original = ref(''); const submitted = ref(false); const deleting = ref<AdmissionStage | null>(null); const discardDialog = ref(false); const message = ref('');
const ordered = computed(() => [...props.stages].sort((a, b) => a.orden - b.orden));
const workflowCount = computed(() => ordered.value.reduce((total, item) => total + item.workflowIds.length, 0));
const errors = computed(() => { const item = editing.value; if (!item) return { nombre: '', inicio: '', cierre: '', publicacion: '' }; return { nombre: !item.nombre.trim() ? 'El nombre de la etapa es obligatorio.' : '', inicio: !item.fechaInicio ? 'Ingrese la fecha y hora de inicio.' : '', cierre: !item.fechaCierre ? 'Ingrese la fecha y hora de cierre.' : (!item.fechaInicio || new Date(item.fechaCierre) > new Date(item.fechaInicio) ? '' : 'El cierre debe ser posterior al inicio.'), publicacion: !item.fechaPublicacion ? 'Ingrese la fecha y hora de publicación.' : (!item.fechaCierre || new Date(item.fechaPublicacion) >= new Date(item.fechaCierre) ? '' : 'La publicación no puede ser anterior al cierre.') }; });
const dirty = computed(() => editing.value ? JSON.stringify(editing.value) !== original.value : false);
const date = (value: string) => value ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'medium' }).format(new Date(value)) : 'Sin definir';
const time = (value: string) => value ? new Intl.DateTimeFormat('es-PE', { timeStyle: 'short' }).format(new Date(value)) : '';
const normalize = (items: AdmissionStage[]) => items.map((item, index) => ({ ...item, orden: index + 1 }));
function begin(stage?: AdmissionStage) { editing.value = stage ? JSON.parse(JSON.stringify(stage)) : { id: `stage-${Date.now()}`, convocatoriaId: props.convocatoriaId, nombre: '', descripcion: '', orden: ordered.value.length + 1, fechaInicio: '', fechaCierre: '', fechaPublicacion: '', workflowIds: [] }; original.value = JSON.stringify(editing.value); submitted.value = false; }
function closeEditor() { if (dirty.value) discardDialog.value = true; else editing.value = null; }
function save() { submitted.value = true; if (!editing.value || Object.values(errors.value).some(Boolean)) return; const next = [...props.stages]; const index = next.findIndex((item) => item.id === editing.value?.id); const value = { ...editing.value, nombre: editing.value.nombre.trim() }; if (index >= 0) next.splice(index, 1, value); else next.push(value); emit('update:stages', normalize(next)); editing.value = null; message.value = 'Etapa guardada localmente.'; }
function move(index: number, delta: number) { const next = ordered.value; const target = index + delta; if (target < 0 || target >= next.length) return; [next[index], next[target]] = [next[target], next[index]]; emit('update:stages', normalize(next)); message.value = 'Orden de etapas actualizado.'; }
function remove() { if (!deleting.value) return; emit('update:stages', normalize(props.stages.filter((item) => item.id !== deleting.value?.id))); deleting.value = null; message.value = 'Etapa eliminada del modelo local.'; }
</script>

<template>
  <template v-if="editing">
    <v-btn variant="text" class="px-0 mb-4" prepend-icon="mdi-arrow-left" @click="closeEditor">Volver a etapas</v-btn>
    <UiParentCard :title="ordered.some(item => item.id === editing?.id) ? 'Configurar etapa' : 'Nueva etapa'" icon="mdi-format-list-numbered"><UiParentCard title="Información general" icon="mdi-file-document-outline" class="mb-6"><v-text-field v-model="editing.nombre" label="Nombre de etapa" :error-messages="submitted ? errors.nombre : ''" /><v-textarea v-model="editing.descripcion" label="Descripción" rows="3" auto-grow hide-details /></UiParentCard><UiParentCard title="Calendario de etapa" icon="mdi-calendar-clock-outline" class="mb-6"><v-row><v-col cols="12" md="4"><v-text-field v-model="editing.fechaInicio" type="datetime-local" label="Fecha y hora de inicio" :error-messages="submitted ? errors.inicio : ''" /></v-col><v-col cols="12" md="4"><v-text-field v-model="editing.fechaCierre" type="datetime-local" label="Cierre de actividades" :error-messages="submitted ? errors.cierre : ''" /></v-col><v-col cols="12" md="4"><v-text-field v-model="editing.fechaPublicacion" type="datetime-local" label="Publicación de resultados" :error-messages="submitted ? errors.publicacion : ''" /></v-col></v-row></UiParentCard><UiParentCard title="Workflows de la etapa" icon="mdi-source-branch"><v-alert type="info" variant="tonal" density="comfortable">Cada etapa puede contener varios workflows. Su diseñador estará disponible en una siguiente fase.</v-alert></UiParentCard><div class="d-flex flex-wrap justify-end ga-3 mt-6"><v-btn variant="outlined" @click="closeEditor">Cancelar</v-btn><v-btn color="primary" @click="save">Guardar etapa</v-btn></div></UiParentCard>
  </template>
  <template v-else>
    <div class="d-flex flex-wrap align-end justify-space-between mb-5 ga-3"><div><div class="text-h6 font-weight-semibold">Etapas del proceso de admisión</div><div class="text-body-2 text-medium-emphasis mb-2">Configura el calendario y orden del proceso.</div><div class="d-flex flex-wrap ga-2"><v-chip size="small" variant="tonal" prepend-icon="mdi-format-list-numbered">{{ ordered.length }} etapas</v-chip><v-chip size="small" variant="tonal" prepend-icon="mdi-source-branch">{{ workflowCount }} workflows</v-chip></div></div><v-btn color="primary" prepend-icon="mdi-plus" @click="begin()">Agregar etapa</v-btn></div>
    <v-alert v-if="message" type="success" variant="tonal" density="compact" closable class="mb-4" @click:close="message = ''">{{ message }}</v-alert>
    <UiParentCard v-if="!ordered.length" title="Etapas del proceso de admisión" icon="mdi-format-list-numbered"><v-empty-state icon="mdi-calendar-outline" title="Aún no hay etapas configuradas" text="Agrega la primera etapa para organizar el proceso de admisión."><template #actions><v-btn color="primary" @click="begin()">Agregar etapa</v-btn></template></v-empty-state></UiParentCard>
    <div v-else class="stages-timeline"><div v-for="(stage, index) in ordered" :key="stage.id" class="stage-entry"><div class="stage-number">{{ index + 1 }}</div><UiParentCard :title="stage.nombre" :subtitle="`${stage.descripcion || 'Sin descripción'} · ${stage.workflowIds.length} workflows`" class="stage-card" content-padding="default"><template #action><v-btn size="small" variant="tonal" color="primary" @click="begin(stage)">Editar etapa</v-btn></template><v-row class="stage-dates"><v-col cols="4"><div class="text-caption text-medium-emphasis">Inicio</div><div class="text-body-2 font-weight-medium">{{ date(stage.fechaInicio) }}</div><div class="text-body-2">{{ time(stage.fechaInicio) }}</div></v-col><v-col cols="4"><div class="text-caption text-medium-emphasis">Cierre</div><div class="text-body-2 font-weight-medium">{{ date(stage.fechaCierre) }}</div><div class="text-body-2">{{ time(stage.fechaCierre) }}</div></v-col><v-col cols="4"><div class="text-caption text-medium-emphasis">Resultados</div><div class="text-body-2 font-weight-medium">{{ date(stage.fechaPublicacion) }}</div><div class="text-body-2">{{ time(stage.fechaPublicacion) }}</div></v-col></v-row><div class="date-milestones" aria-label="Hitos del calendario"><span>Inicio</span><span>Cierre</span><span>Resultados</span></div><div class="d-flex justify-end ga-1 mt-3"><v-tooltip text="Subir etapa"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-arrow-up" variant="text" size="small" :disabled="index === 0" aria-label="Subir etapa" @click="move(index, -1)" /></template></v-tooltip><v-tooltip text="Bajar etapa"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-arrow-down" variant="text" size="small" :disabled="index === ordered.length - 1" aria-label="Bajar etapa" @click="move(index, 1)" /></template></v-tooltip><v-tooltip text="Eliminar etapa"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-delete-outline" variant="text" color="error" size="small" aria-label="Eliminar etapa" @click="deleting = stage" /></template></v-tooltip></div></UiParentCard></div></div>
  </template>
  <UiModal :show="Boolean(deleting)" title="Eliminar etapa" persistent @update:show="deleting = null"><p>Se eliminará <b>{{ deleting?.nombre }}</b> del modelo local de demostración.</p><template #footer-actions><v-btn variant="text" @click="deleting = null">Cancelar</v-btn><v-btn color="error" @click="remove">Eliminar</v-btn></template></UiModal><UiModal v-model:show="discardDialog" title="Descartar cambios"><p>Hay modificaciones sin guardar. ¿Desea descartarlas?</p><template #footer-actions><v-btn variant="text" @click="discardDialog = false">Continuar editando</v-btn><v-btn color="primary" @click="discardDialog = false; editing = null">Descartar cambios</v-btn></template></UiModal>
</template>

<style scoped>
.stages-timeline { position: relative; padding-left: 3.25rem; }.stages-timeline::before { content: ''; position: absolute; inset: 1rem auto 1.5rem 1rem; width: 2px; background: rgb(var(--v-theme-borderColor)); }.stage-entry { position: relative; padding-bottom: 1rem; }.stage-number { position: absolute; left: -3.25rem; top: 1.1rem; z-index: 1; display: grid; place-items: center; width: 2rem; height: 2rem; border-radius: 50%; background: rgb(var(--v-theme-primary)); color: rgb(var(--v-theme-on-primary)); font-weight: 600; }.stage-card :deep(.v-card-item) { padding-bottom: .75rem; }.date-milestones { display: grid; grid-template-columns: repeat(3, 1fr); align-items: center; margin-top: .25rem; text-align: center; font-size: .75rem; }.date-milestones span { position: relative; display: grid; justify-items: center; gap: .25rem; }.date-milestones span::before { content: ''; position: relative; z-index: 1; width: .65rem; height: .65rem; border: 2px solid rgb(var(--v-theme-primary)); border-radius: 50%; background: rgb(var(--v-theme-surface)); }.date-milestones span:not(:last-child)::after { content: ''; position: absolute; top: .28rem; left: 50%; width: 100%; height: 2px; background: rgb(var(--v-theme-borderColor)); } @media (max-width: 600px) { .stages-timeline { padding-left: 2.75rem; }.stage-number { left: -2.75rem; }.date-milestones { display: none; } }
</style>
